mapper.select:
SELECT DISTINCT s.* 
FROM student s
LEFT JOIN stu_region sr ON s.id = sr.stu_id
LEFT JOIN stu_language sl ON s.id = sl.stu_id
LEFT JOIN stu_certificate sc ON s.id = sc.stu_id
LEFT JOIN stu_internship si ON s.id = si.stu_id
LEFT JOIN stu_speciality ss ON s.id = ss.stu_id


        OR s.id = #{query.id}


        OR s.stu_id = #{query.stuId}


        OR s.name LIKE CONCAT('%', #{query.name}, '%')


        OR s.age >= #{query.minAge}


        OR s.age <= #{query.maxAge}


        OR s.gender = #{query.gender}


        OR s.nation LIKE CONCAT('%', #{query.nation}, '%')


        OR s.major LIKE CONCAT('%', #{query.major}, '%')


        OR s.degree = #{query.degree}


        OR s.graduation_year >= #{query.minGraduationYear}


        OR s.graduation_year <= #{query.maxGraduationYear}


        OR s.internship >= #{query.minInternship}


        OR s.internship <= #{query.maxInternship}


        OR sr.city LIKE CONCAT('%', #{query.city}, '%')


        OR sr.province LIKE CONCAT('%', #{query.province}, '%')


        OR sl.language LIKE CONCAT('%', #{query.language}, '%')


        OR sl.level LIKE CONCAT('%', #{query.languageLevel}, '%')


        OR sc.cert_name LIKE CONCAT('%', #{query.certName}, '%')


        OR sc.level LIKE CONCAT('%', #{query.certLevel}, '%')


        OR si.company LIKE CONCAT('%', #{query.internshipCompany}, '%')


        OR ss.speciality LIKE CONCAT('%', #{query.speciality}, '%')


ORDER BY s.id
